for name, items in EX.items():
    src = open(f"{name}.txt", encoding="utf8").read().strip().split("\n\n")
    out = []
    for part in src:
        out.append(part)
        body = part.split("|", 1)[-1].strip() if "|" in part else ""
        for anc, new in items:
            if body.startswith(anc) and new not in out: out.append(new)
    done = sum(1 for o in out if any(o == n for _, n in items))
    if done != len(items): print("ANCRE MANQUANTE", name, done, len(items))
    open(f"{name}.txt", "w", encoding="utf8").write("\n\n".join(out) + "\n")
